/* Adom newbie panel - the ONE implementation every dock dashboard mounts.
 * Published in adom-ui-design. Do not fork it: fix it here and every app gets the fix.
 * Self-contained: no network, no deps, fonts embedded. Serve it next to your dashboard
 * and <script src="newbie-panel.js"></script>, or inline its text into your page.
 */
(function (root) {
  'use strict';
  var CSS = `
@font-face{font-family:'Familjen Grotesk';font-style:normal;font-weight:400 700;font-display:swap;
  src:url(data:font/woff2;base64,) format('woff2-variations');}
@font-face{font-family:'Satoshi';font-style:normal;font-weight:300 900;font-display:swap;
  src:url(data:font/woff2;base64,) format('woff2-variations');}

.anp-wrap{container-type:inline-size; container-name:anp; width:100%;}
.anp{
  --anp-surface:#161b22; --anp-line:#30363d; --anp-teal:#00b8b1;
  --anp-text:#e6edf3; --anp-muted:#8b949e; --anp-row:#262d36;
  --anp-display:'Familjen Grotesk',ui-sans-serif,system-ui,sans-serif;
  --anp-body:'Satoshi',ui-sans-serif,system-ui,sans-serif;
  box-sizing:border-box; width:100%; margin:16px 0 20px; padding:18px 20px 20px;
  background:var(--anp-surface); border:1px solid var(--anp-line);
  border-left:3px solid var(--anp-teal); border-radius:12px;
  font-family:var(--anp-body); color:var(--anp-text);
  display:grid; grid-template-areas:"head head" "left right";
  grid-template-columns:220px minmax(0,1fr); column-gap:24px; row-gap:14px;
}
.anp *,.anp *::before,.anp *::after{box-sizing:border-box;}
.anp[hidden]{display:none;}

.anp-head{grid-area:head; position:relative; padding-right:40px;}
.anp-head h2{margin:0; font:600 15px/1.3 var(--anp-display); color:var(--anp-text); letter-spacing:-.01em;}
.anp-head p{margin:6px 0 0; font:400 13.5px/1.5 var(--anp-body); color:var(--anp-muted); max-width:78ch;}
.anp-head p b{color:var(--anp-teal); font-weight:500;}

.anp-left{grid-area:left; display:flex; flex-direction:column; align-items:flex-start; gap:8px;}
.anp-right{grid-area:right; min-width:0;}

.anp-demo{
  display:inline-flex; align-items:center; gap:9px; white-space:nowrap;
  font:600 14px/1 var(--anp-display); color:#05221f;
  background:var(--anp-teal); border:0; border-radius:8px; padding:10px 18px;
  cursor:pointer; transition:filter .15s ease;
}
.anp-demo:hover{filter:brightness(1.08);}
.anp-demo:active{filter:brightness(.94);}
.anp-demo:focus-visible{outline:2px solid var(--anp-teal); outline-offset:3px;}
.anp-demo svg{width:14px;height:14px;flex:0 0 auto;}
.anp-meta{font:400 12px/1.4 var(--anp-body); color:var(--anp-muted);}

.anp-tbl{width:100%; max-width:720px; border-collapse:collapse; table-layout:fixed;}
.anp-tbl td{padding:0; border:0; border-bottom:1px solid var(--anp-row); height:40px; vertical-align:middle;}
.anp-tbl tr:last-child td{border-bottom:0;}
.anp-tbl tr{cursor:pointer;}
.anp-tbl tr:hover td{background:rgba(255,255,255,.03);}
.anp-phrase{width:auto; min-width:0;}
.anp-phrase span{display:block; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;
  font:400 14px/1.4 var(--anp-body); color:var(--anp-text);}
.anp-phrase b{color:var(--anp-teal); font-weight:400;}
.anp-acts{width:72px; white-space:nowrap; text-align:right;}
.anp-acts .anp-ib + .anp-ib{margin-left:6px;}

.anp-ib{display:inline-flex; align-items:center; justify-content:center; width:28px; height:28px;
  padding:0; background:none; border:0; border-radius:6px; color:var(--anp-muted); cursor:pointer;
  transition:color .15s ease, background .15s ease;}
.anp-ib:hover{color:var(--anp-teal); background:rgba(255,255,255,.05);}
.anp-ib:focus-visible{outline:2px solid var(--anp-teal); outline-offset:1px;}
.anp-ib svg{width:16px;height:16px;display:block;}
.anp-ib[disabled]{opacity:.45; cursor:default;}

.anp-x{position:absolute; top:-2px; right:0; width:28px; height:28px; padding:0; background:none;
  border:0; border-radius:6px; color:var(--anp-muted); cursor:pointer;}
.anp-x:hover{color:var(--anp-text); background:rgba(255,255,255,.06);}
.anp-x:focus-visible{outline:2px solid var(--anp-teal); outline-offset:1px;}
.anp-x svg{width:14px;height:14px;display:block;margin:auto;}

@container anp (max-width:699px){
  .anp{grid-template-areas:"head" "left" "right"; grid-template-columns:minmax(0,1fr); row-gap:12px;}
  .anp-left{flex-direction:row; align-items:center; gap:12px;}
}

.anp-toasts{position:fixed; left:50%; bottom:22px; transform:translateX(-50%); z-index:99999;
  display:flex; flex-direction:column-reverse; gap:8px; pointer-events:none;}
.anp-toast{pointer-events:auto; display:flex; align-items:center; gap:10px; max-width:min(92vw,520px);
  padding:10px 14px; border-radius:8px; border:1px solid var(--anp-line,#30363d);
  background:#1c2230; color:#e6edf3; font:400 13.5px/1.4 'Satoshi',ui-sans-serif,system-ui,sans-serif;
  box-shadow:0 10px 30px rgba(0,0,0,.45); animation:anp-in .18s ease;}
.anp-toast.ok{border-left:3px solid #3fb950;}
.anp-toast.err{border-left:3px solid #f85149;}
.anp-toast.info{border-left:3px solid #00b8b1;}
@keyframes anp-in{from{opacity:0;transform:translateY(6px);}to{opacity:1;transform:none;}}
@media (prefers-reduced-motion:reduce){.anp-toast{animation:none;}}

.anp-tip{position:fixed; z-index:99999; pointer-events:none; padding:6px 9px; border-radius:6px;
  background:#0d1117; border:1px solid #30363d; color:#e6edf3; text-transform:none;
  font:400 12px/1.3 'Satoshi',ui-sans-serif,system-ui,sans-serif; box-shadow:0 6px 20px rgba(0,0,0,.5);
  opacity:0; transition:opacity .18s ease;}
.anp-tip.on{opacity:1;}
`;
  var ICON = {
    copy: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="9" y="9" width="12" height="12" rx="2"/><path d="M6 15H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h8a2 2 0 0 1 2 2v1"/></svg>',
    send: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M21.5 2.5 10.5 13.5"/><path d="M21.5 2.5 14.8 21.5l-4.3-8-8-4.3z"/></svg>',
    play: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M6 4l14 8-14 8z"/></svg>',
    x:    '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" aria-hidden="true"><path d="M5 5l14 14M19 5 5 19"/></svg>',
    help: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M9.2 9.3a2.9 2.9 0 0 1 5.6 1c0 1.9-2.8 2.4-2.8 4"/><path d="M12 17.6h.01"/></svg>'
  };
  /* The two-column layout needs, inside the panel's padding:
   *   phrase cell 336 + action column 72 + 8 gutter = 416 for the right column
   *   left column 220 + column gap 24 + 416          = 660 content
   *   + 20 left padding + 20 right padding           = 700 PANEL border-box
   * That is where 700 comes from. It is a PANEL width, not a viewport width, so it is the
   * same number in every app regardless of that app's page chrome. */
  var TWO_COL_MIN = 700, PHRASE_BUDGET = 336;
  var MIN_API = [1, 0, 142];

  /* Hydrogen 1.0.187+ answers a send with a JOB and reports progress on
   * GET /ai-threads/run-prompt/status?job=<uuid>. Measured on the VM: tab visible ~0.1s,
   * session id ~2.5s, sent by 3-5s, a trivial answer done ~8s. One poll a second is the
   * right cadence for that shape, and it is an in-memory read on the other end. */
  var PHASE = {
    opening:               'Opening a new AI chat…',
    prefilled:             'Prompt ready…',
    submitted:             'Sent, waiting for the AI…',
    working:               'The AI is working…',
    needs_you:             'The AI needs you. Open the tab.',
    done:                  'Done.',
    submit_failed:         'The prompt is in the tab. Press Enter there to send it.',
    submitted_unidentified:'Sent, but the AI never checked in.',
    submit_unconfirmed:    'Sent, but delivery was not confirmed.',
    still_working:         'The AI is still working. Open the tab.'
  };

  function css() {
    if (document.getElementById('anp-css')) return;
    var s = document.createElement('style');
    s.id = 'anp-css'; s.textContent = CSS;
    document.head.appendChild(s);
  }
  function el(tag, cls, html) {
    var n = document.createElement(tag);
    if (cls) n.className = cls;
    if (html != null) n.innerHTML = html;
    return n;
  }
  function esc(s) {
    return String(s).replace(/[&<>"]/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c];
    });
  }
  /* Highlight the trigger noun. Built with RegExp(), never a literal, because a dashboard
   * assembled as a JS template literal turns \b into a BACKSPACE and the boundaries vanish
   * silently: the regex still matches, just too greedily. (nb, 2026-08-25) */
  function mark(phrase, noun) {
    var safe = esc(phrase);
    if (!noun) return safe;
    var re = new RegExp('\\b(' + esc(noun).replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + ')\\b', 'gi');
    return safe.replace(re, '<b>$1</b>');
  }

  /* ---- copy, with a fallback that does not need the async clipboard ------
   * navigator.clipboard.writeText needs a secure context AND, in several embedded webviews,
   * transient user activation plus a clipboard-write permission that is simply absent. In
   * ah's webview it rejects with NotAllowedError, so the ONLY path the panel had would fail
   * and the user got "Could not reach the clipboard" on a button that looks like it works.
   * The execCommand path is deprecated but synchronous, needs no permission, and works in
   * exactly the contexts the async API refuses. Try the modern one, fall back, and only then
   * report failure. */
  function copyText(text) {
    return new Promise(function (resolve, reject) {
      function legacy() {
        try {
          var ta = document.createElement('textarea');
          ta.value = text;
          ta.setAttribute('readonly', '');
          ta.style.cssText = 'position:fixed;top:0;left:-9999px;opacity:0';
          document.body.appendChild(ta);
          ta.select(); ta.setSelectionRange(0, ta.value.length);
          var ok = document.execCommand && document.execCommand('copy');
          ta.remove();
          ok ? resolve('legacy') : reject(new Error('execCommand refused'));
        } catch (e) { reject(e); }
      }
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(text).then(function () { resolve('async'); }, legacy);
      } else legacy();
    });
  }

  /* ---- toasts ---------------------------------------------------------- */
  var toastHost = null;
  function toast(msg, kind, ms) {
    if (!toastHost) { toastHost = el('div', 'anp-toasts'); document.body.appendChild(toastHost); }
    var t = el('div', 'anp-toast ' + (kind || 'info'), esc(msg));
    toastHost.appendChild(t);
    /* retextable, so a long send can narrate its phases in ONE toast instead of
     * stacking six of them on top of each other. */
    t.setText = function (next) { t.innerHTML = esc(next); return t; };
    setTimeout(function () { t.remove(); }, ms || (kind === 'err' ? 7000 : 4000));
    return t;
  }

  /* ---- one tooltip, viewport-clamped, never a title attribute ----------- */
  var tip = null, tipT = null;
  function tipFor(node, text) {
    node.setAttribute('aria-label', text);
    node.removeAttribute('title');          // two tooltips on one control is a bug
    node.__anpSetTip = function (t) { text = t; if (tip && tip.classList.contains('on')) tip.textContent = t; };
    node.addEventListener('mouseenter', function (e) {
      clearTimeout(tipT);
      tipT = setTimeout(function () {
        if (!tip) { tip = el('div', 'anp-tip'); document.body.appendChild(tip); }
        tip.textContent = text; tip.classList.add('on');
        var r = node.getBoundingClientRect(), w = tip.offsetWidth, h = tip.offsetHeight, M = 8;
        var left = r.left + r.width / 2 - w / 2, top = r.top - h - 8;
        if (top < M) top = r.bottom + 8;
        left = Math.max(M, Math.min(left, document.documentElement.clientWidth - w - M));
        top = Math.max(M, Math.min(top, document.documentElement.clientHeight - h - M));
        tip.style.left = left + 'px'; tip.style.top = top + 'px';
      }, 600);
    });
    ['mouseleave', 'blur', 'click'].forEach(function (ev) {
      node.addEventListener(ev, function () {
        clearTimeout(tipT); if (tip) tip.classList.remove('on');
      });
    });
  }

  /* ---- send to a new AI thread ----------------------------------------- */
  function verNum(s) {
    var p = String(s || '').split('.').map(function (x) { return parseInt(x, 10) || 0; });
    return [p[0] || 0, p[1] || 0, p[2] || 0];
  }
  function verGte(a, b) {
    for (var i = 0; i < 3; i++) { if (a[i] > b[i]) return true; if (a[i] < b[i]) return false; }
    return true;
  }
  function gate(base) {
    /* NUMERIC compare, split on dots. A string compare passes "1.0.99", which is older and
     * still carries the crash. Fail OPEN if the probe itself is unreachable. */
    return fetch(base + '/updater/status', { cache: 'no-store' })
      .then(function (r) { return r.json(); })
      .then(function (j) {
        var v = (j && j.updater && j.updater.current_version) || '0.0.0';
        return { ok: verGte(verNum(v), MIN_API), version: v };
      })
      .catch(function () { return { ok: true, version: null, open: true }; });
  }
  function send(base, phrase, appName, slug, onProgress) {
    return gate(base).then(function (g) {
      if (!g.ok) throw new Error('Adom needs updating to send prompts (found ' + g.version + ', needs 1.0.142). Run: adom update');
      var ctl = new AbortController(), timer = setTimeout(function () { ctl.abort(); }, 120000);
      /* ONE call. POST /ai-threads/new NEVER returns an id, so a two-step create-then-run
       * flow fails 100% of the time and looks like a platform fault. */
      return fetch(base + '/ai-threads/run-prompt', {
        method: 'POST', signal: ctl.signal,
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({
          "new": true, prompt: phrase, submit: true,
          name: appName + ' - say it', tags: ['dock:' + slug]
        })
      }).then(function (r) { return r.json().then(function (j) { return { status: r.status, j: j }; }); })
        .then(function (res) {
          clearTimeout(timer);
          var j = res.j || {};
          if (!(res.status >= 200 && res.status < 300))
            throw new Error((j._hints && j._hints.note) || j.error || ('AI threads returned ' + res.status));
          /* PRE-1.0.187 SHAPE, kept because older Hydrogen builds still answer this way.
           * delivered_to is an ARRAY; a thread that opened but did not confirm delivery is
           * NOT a failure, and retrying it double-sends. */
          var dt = j.delivered_to, arr = Array.isArray(dt) ? dt : (dt ? [dt] : []);
          if (arr.length || (j.inject && j.inject.delivered_in_conversation)) return { state: 'delivered' };
          /* 1.0.187+ returns in well under a second with a JOB, not a delivery. ok:true means
           * the job STARTED. delivered_to is never filled on this path any more, so without
           * the poll below every send would report "delivery not confirmed" forever. */
          if (!j.job) return { state: 'opened', hint: j._hints && j._hints.note };
          var started = Date.now(), missing = false;
          return new Promise(function (resolve) {
            (function tick() {
              /* the deadline is checked in BOTH paths. Checking it only after a successful
               * poll leaves a dashboard whose server stops answering polling forever. */
              function again() {
                if (Date.now() - started > 120000)
                  return resolve({ state: 'opened', hint: 'no confirmation within 120s' });
                setTimeout(tick, 1000);
              }
              fetch(base + '/ai-threads/run-prompt/status?job=' + encodeURIComponent(j.job))
                .then(function (r) {
                  /* THE STATUS ROUTE IS A THIRD PROXY ROUTE. Dashboards proxy /updater/status
                   * and POST /ai-threads/run-prompt only. If this one was never added, every
                   * poll 404s and the user watches "Opening…" for the full 120s before a
                   * hedge, which is worse than the behaviour this replaced. Fail FAST and say
                   * exactly which route is missing instead of hanging. */
                  if (r.status === 404) { missing = true; return null; }
                  return r.json();
                })
                .then(function (st) {
                  if (missing) return resolve({ state: 'opened', phase: 'no_status_route',
                    hint: 'Your AI chat opened. This app does not proxy GET ' +
                          '/ai-threads/run-prompt/status yet, so progress cannot be shown.' });
                  var state = (st.job && st.job.state) || '';
                  if (typeof onProgress === 'function') { try { onProgress(state, st.job); } catch (e) {} }
                  /* working or later IS sent, for the user-facing toast. */
                  if (state === 'working' || state === 'done' || state === 'needs_you' ||
                      state === 'still_working') return resolve({ state: 'delivered', phase: state });
                  if (state === 'submit_failed' || state === 'submitted_unidentified' ||
                      state === 'submit_unconfirmed')
                    return resolve({ state: 'opened', phase: state,
                                     hint: (st.job && (st.job.error || st.job.note)) || state });
                  again();
                })
                .catch(again);
            })();
          });
        })
        .catch(function (e) {
          clearTimeout(timer);
          if (e.name === 'AbortError') return { state: 'opened', hint: 'no answer within 120s' };
          throw e;
        });
    });
  }

  /* ---- mount ------------------------------------------------------------ */
  function mount(cfg) {
    css();
    var host = typeof cfg.mount === 'string' ? document.querySelector(cfg.mount) : cfg.mount;
    if (!host) throw new Error('newbie panel: mount target not found: ' + cfg.mount);
    var noun = cfg.app || '';
    var slug = cfg.slug || noun.replace(/\s+/g, '-');
    var appName = cfg.appName || noun;
    var base = cfg.apiBase == null ? '' : cfg.apiBase;
    var key = 'anp:' + slug + ':open';

    var wrap = el('div', 'anp-wrap');
    var panel = el('section', 'anp');
    panel.setAttribute('aria-label', 'Say it: sample prompts for ' + appName);

    var head = el('div', 'anp-head');
    head.appendChild(el('h2', null, 'Say it'));
    head.appendChild(el('p', null,
      "You never need this page's buttons: just tell your AI what you want, using the words <b>" +
      esc(noun) + "</b>. Copy a phrase, or send it straight to a new AI thread."));
    var x = el('button', 'anp-x', ICON.x);
    x.type = 'button'; tipFor(x, 'Close this panel');
    head.appendChild(x);
    panel.appendChild(head);

    var left = el('div', 'anp-left');
    var demo = el('button', 'anp-demo', ICON.play + '<span>' + esc((cfg.demo && cfg.demo.label) || 'Play the demo') + '</span>');
    demo.type = 'button';
    demo.addEventListener('click', function () {
      if (cfg.demo && typeof cfg.demo.onPlay === 'function') cfg.demo.onPlay();
      else toast('This dashboard has no demo wired up yet', 'err');
    });
    left.appendChild(demo);
    if (cfg.demo && cfg.demo.meta) left.appendChild(el('span', 'anp-meta', esc(cfg.demo.meta)));
    panel.appendChild(left);

    var right = el('div', 'anp-right');
    var tbl = el('table', 'anp-tbl');
    var tb = el('tbody');
    (cfg.phrases || []).slice(0, 6).forEach(function (phrase) {
      var tr = el('tr');
      var td = el('td', 'anp-phrase', '<span>“' + mark(phrase, noun) + '”</span>');
      var ta = el('td', 'anp-acts');

      var cp = el('button', 'anp-ib', ICON.copy); cp.type = 'button';
      tipFor(cp, 'Copy this phrase');
      cp.addEventListener('click', function (e) {
        e.stopPropagation();
        copyText(phrase)
          .then(function () { toast('Copied. Paste it to your AI.', 'ok'); })
          .catch(function () { toast('Could not reach the clipboard. Select the phrase and copy it.', 'err'); });
      });

      var sd = el('button', 'anp-ib', ICON.send); sd.type = 'button';
      tipFor(sd, 'Send to a new AI thread');
      sd.addEventListener('click', function (e) {
        e.stopPropagation();
        if (sd.disabled) return;
        sd.disabled = true;
        var pending = toast('Opening a new AI thread…', 'info', 120000);
        send(base, phrase, appName, slug, function (state, job) {
          if (PHASE[state]) pending.setText(PHASE[state]);
          if (typeof cfg.onProgress === 'function') { try { cfg.onProgress(state, job); } catch (e) {} }
        }).then(function (r) {
          pending.remove();
          if (r.state === 'delivered') toast('Sent. Your AI thread has the prompt.', 'ok');
          else toast('Thread opened, delivery not confirmed. Check your AI threads before sending again.', 'info', 8000);
        }).catch(function (err) {
          pending.remove();
          toast(err.message || 'Could not send the prompt.', 'err');
        }).then(function () { sd.disabled = false; });
      });

      ta.appendChild(cp); ta.appendChild(sd);
      tr.appendChild(td); tr.appendChild(ta);
      tr.addEventListener('click', function () { cp.click(); });
      tb.appendChild(tr);
    });
    tbl.appendChild(tb); right.appendChild(tbl); panel.appendChild(right);
    wrap.appendChild(panel); host.appendChild(wrap);

    /* the header ? is a real TOGGLE, both ways, with aria-pressed and a label that swaps */
    var toggleBtn = typeof cfg.toggleButton === 'string'
      ? document.querySelector(cfg.toggleButton) : cfg.toggleButton;
    /* setOpen(open, remember, source)
     * source is 'user' when a person clicked the X or the header toggle, and 'api' when the
     * app called open()/close() itself. It is passed to onToggle, because an app with a
     * graduation policy calls open()/close() from inside its own onToggle handler: without a
     * source the callback cannot tell its own action from a person's, so graduating the panel
     * open pins it open forever and graduating it closed marks it user-dismissed. It looks
     * like "the panel sometimes ignores graduation". (lbr, 2026-08-25) */
    function setOpen(open, remember, source) {
      panel.hidden = !open;
      wrap.style.display = open ? '' : 'none';   /* no dead margin when collapsed */
      if (toggleBtn) {
        var label = open ? 'Hide the sample prompts' : 'Show the sample prompts';
        toggleBtn.setAttribute('aria-pressed', open ? 'true' : 'false');
        toggleBtn.setAttribute('aria-label', label);
        /* the TOOLTIP has to swap with the state too, or a person with the panel already in
         * front of them hovers the control and is told it will show them the panel */
        if (toggleBtn.__anpSetTip) toggleBtn.__anpSetTip(label);
      }
      if (remember !== false) { try { localStorage.setItem(key, open ? '1' : '0'); } catch (e) {} }
      if (typeof cfg.onToggle === 'function') cfg.onToggle(open, source || 'api');
    }
    x.addEventListener('click', function () { setOpen(false, true, 'user'); });
    if (toggleBtn) {
      if (!toggleBtn.innerHTML.trim()) toggleBtn.innerHTML = ICON.help;
      tipFor(toggleBtn, 'Show the sample prompts');
      toggleBtn.addEventListener('click', function () { setOpen(panel.hidden, true, 'user'); });
    }
    var saved = null;
    try { saved = localStorage.getItem(key); } catch (e) {}
    setOpen(saved === null ? true : saved === '1', false);

    /* authoring guard: a phrase that truncates at rest is an authoring bug, and it eats the
     * trigger noun because the noun is usually the last word. Warn loudly at build time. */
    var probe = el('span'); probe.style.cssText = 'position:absolute;visibility:hidden;white-space:nowrap';
    document.body.appendChild(probe);
    var over = [];
    (cfg.phrases || []).forEach(function (p) {
      probe.style.font = '400 14px/1.4 Satoshi,ui-sans-serif,system-ui,sans-serif';
      probe.textContent = '“' + p + '”';
      var need = Math.ceil(probe.getBoundingClientRect().width);
      if (need > PHRASE_BUDGET) over.push({ phrase: p, needs: need, budget: PHRASE_BUDGET });
    });
    probe.remove();
    if (over.length) {
      console.warn('[newbie-panel] ' + over.length + ' phrase(s) will truncate at the resting width. ' +
        'Shorten them, and lead with the trigger noun so a clip costs a detail not the routing words.', over);
    }

    return {
      panel: panel,
      open:   function (o) { setOpen(true,  !(o && o.remember === false), 'api'); },
      close:  function (o) { setOpen(false, !(o && o.remember === false), 'api'); },
      toggle: function () { setOpen(panel.hidden, true, 'api'); },
      isOpen: function () { return !panel.hidden; },
      overBudget: over, toast: toast, selfCheck: function () { return selfCheck(panel); }
    };
  }

  /* ---- selfCheck: prove conformance from one call ---------------------- */
  var CANON = {
    'card background':      ['backgroundColor', 'rgb(22, 27, 34)'],
    'card border':          ['borderTopWidth',  'snap:1'],
    'card border colour':   ['borderTopColor',  'rgb(48, 54, 61)'],
    'card accent edge':     ['borderLeftWidth', 'snap:3'],
    'card radius':          ['borderRadius',    '12px'],
    'card padding':         ['padding',         '18px 20px 20px'],
    'column gap':           ['columnGap',       '24px']
  };
  /* selfCheck(panel) - pass the panel explicitly when the page mounts more than one, or
   * mounts into a shadow root. The no-arg form takes the FIRST .anp in the light DOM, which
   * is right for the single-panel case and silently wrong for the others. Returns
   * {ok:false, error} rather than throwing when there is no panel. (chip-fetcher, 2026-08-25) */
  function selfCheck(panel) {
    panel = panel || document.querySelector('.anp');
    if (!panel) return { ok: false, error: 'no .anp panel on the page' };
    /* REFUSE TO REPORT FROM A COLLAPSED LAYOUT. An unforegrounded tab returns zero-height
     * rects while computed styles still resolve normally, so selfCheck produced EIGHT GREEN
     * ROWS beside two red ones: "panel gutter: 0px left, 744px right" and "columns: want 1,
     * got 3". That mixed shape is far more dangerous than an all-zero one, because it reads
     * as a specific layout regression rather than an invalid run, and project-manager nearly
     * filed it as a bug. A refusal cannot be misread. (project-manager, 2026-08-25.) */
    var w0 = Math.round(panel.getBoundingClientRect().width);
    /* rows: [] is deliberate. The refusal previously omitted the key entirely, and EVERY
     * caller does r.rows.map(...) because every healthy result has rows, so a correct refusal
     * arrived at the caller as "Cannot read properties of undefined (reading 'map')" and read
     * like harness noise. kicad hit exactly that and logged it as its own crash. A guard whose
     * failure mode is a TypeError in someone else's stack is a guard that will be misread. */
    if (w0 === 0) return { ok: false, invalid: true, rows: [],
      error: 'panel measures 0px wide: this tab is not foregrounded (or the panel is hidden), ' +
             'so every layout row would ' +
             'be computed from a collapsed pane while the style rows pass normally. Activate ' +
             'the tab by name (or open the panel) and re-run. No rows reported, because a ' +
             'partial result from an unrendered pane looks like a real bug.' };
    var cs = getComputedStyle(panel), rows = [], ok = true;
    /* Chrome reports the USED border-width, snapped to whole device pixels, so a declared
     * 1px reads as 0.666667px at dpr 1.5. Compare against the snapped value, not the
     * declared one, or every panel fails a check it actually passes. */
    function snap(declared) {
      var dpr = window.devicePixelRatio || 1;
      return (Math.max(1, Math.floor(declared * dpr)) / dpr) + 'px';
    }
    Object.keys(CANON).forEach(function (k) {
      var want = CANON[k][1];
      var got = cs[CANON[k][0]], declared = CANON[k][1];
      /* Border widths need BOTH candidates accepted. Chrome reports the USED width, snapped
       * to whole device pixels, on some surfaces (ah's webview and pup on a dpr-1.5 laptop
       * both return 0.666667px for a declared 1px) and reports the DECLARED width on others
       * (an emulated dpr returns 1px at every ratio). Accepting only one of the two fails a
       * correct panel in the other environment, and at dpr 1.5 specifically, which is the
       * machine this fleet is reviewed on. Found by nb, 2026-08-25. */
      var pass;
      if (declared.indexOf('snap:') === 0) {
        var d = parseFloat(declared.slice(5)), g = parseFloat(got);
        pass = Math.abs(g - d) < 0.01 || Math.abs(g - parseFloat(snap(d))) < 0.01;
        want = d + 'px or ' + snap(d);
      } else {
        pass = (parseFloat(want) && parseFloat(got))
          ? Math.abs(parseFloat(got) - parseFloat(want)) < 0.01
          : got === want;
      }
      if (!pass) ok = false;
      rows.push({ what: k, want: want, got: got, pass: pass });
    });
    var copies = panel.querySelectorAll('.anp-acts .anp-ib:first-child');
    var xs = {}; [].forEach.call(copies, function (b) { xs[Math.round(b.getBoundingClientRect().x)] = 1; });
    var aligned = Object.keys(xs).length <= 1;
    if (!aligned) ok = false;
    rows.push({ what: 'copy icons in one column', want: '1 x-position', got: Object.keys(xs).length + ' x-positions', pass: aligned });
    var cols = cs.gridTemplateColumns.split(' ').filter(Boolean).length;
    rows.push({ what: 'columns at this width', want: panel.getBoundingClientRect().width >= TWO_COL_MIN ? '2' : '1',
                got: String(cols), pass: true });
    /* THE GUTTER ROW. Four apps measured at the SAME 744px pane reported panel widths of
     * 734, 735, 702 and 694, because each page put a different amount of its own padding
     * around the mount point. 694 is under the 700 threshold, so that app rendered ONE
     * column while the other three rendered TWO, at an identical pane width. The panel was
     * conformant in all four; the PAGE around it was not. The fleet gutter is 16px a side,
     * so the panel's border box is the pane minus 32. */
    /* Measure against the panel's OWN CONTAINING BLOCK, never documentElement.
     * The first version compared to documentElement.clientWidth, which silently assumes the
     * PAGE scrolls. An app-shell dashboard (position:fixed shell, 44px header, scroller on an
     * inner .app-body) has no document scrollbar, so clientWidth is the full pane and the
     * inner scrollbar is charged to content instead: a correctly built app-shell page fails
     * by exactly one scrollbar width, and only pages that happen to scroll at document level
     * pass. Since app-shell is the prescribed structure, the check was failing the apps that
     * followed the skill. The containing block is scrollbar-agnostic and still catches the
     * real defect, which is a page adding its own padding around the mount point.
     * (parts-search, 2026-08-25, from reading the implementation rather than the prose.) */
    /* Measure BOTH INSETS AGAINST THE PANE, and never against a named element.
     * Two earlier versions asked the wrong element how wide the world is. documentElement
     * assumes the page scrolls, and fails every app-shell dashboard by one scrollbar width.
     * The mount div assumes the 16px lives on the mount div, and reds a visually perfect page
     * that puts the gutter on a shared outer container instead. Both encode a STRUCTURE the
     * fleet was never promised. What the contract actually says is where the panel's EDGES
     * land, so measure exactly that: find the nearest scrolling ancestor (or the document),
     * and check the panel sits 16px inside its client box on both sides. Structure-agnostic:
     * it does not care which element carries the padding, or how many wrappers sit between.
     * (pup found the mount-div version would red an outer-container page, before six apps
     * adopted the pattern I had recommended; parts-search found the documentElement one.) */
    var sc = panel.parentElement;
    while (sc && sc !== document.body) {
      /* A DECLARED scroller is the pane whether or not it is scrolling RIGHT NOW. Requiring
       * it to overflow was a bug with a nastier shape than the two before it: with
       * scrollbar-gutter:stable (which this pack mandates, so results arriving cause no
       * reflow) the track is reserved even when nothing overflows, so the loop walked PAST
       * the real pane, fell back to documentElement, and reported the right inset over by
       * one scrollbar width. The SAME PAGE passed when populated and failed when empty, and
       * empty is a dashboard's first-load state. Predicted from a code read by parts-search
       * and confirmed here: 16 left / 31 right, exact. */
      var so = getComputedStyle(sc).overflowY;
      if (so === 'auto' || so === 'scroll') break;
      sc = sc.parentElement;
    }
    var paneLeft, paneW;
    if (sc && sc !== document.body) { paneLeft = sc.getBoundingClientRect().left; paneW = sc.clientWidth; }
    else { paneLeft = 0; paneW = document.documentElement.clientWidth; }
    var pr = panel.getBoundingClientRect();
    var insetL = Math.round(pr.left - paneLeft);
    var insetR = Math.round(paneLeft + paneW - pr.right);
    var gutterOk = Math.abs(insetL - 16) <= 2 && Math.abs(insetR - 16) <= 2;
    if (!gutterOk) ok = false;
    rows.push({ what: 'panel gutter', want: '16px inset both sides',
                got: insetL + 'px left, ' + insetR + 'px right', pass: gutterOk });
    /* THE LEFT-EDGE ROW closes the hole the gutter row cannot see. The gutter row measures
     * against whatever element the app mounts INTO, so an app that mounts into a wrapper
     * which itself carries padding passes while sitting inset from its neighbours, and the
     * fleet mismatch comes back in a form the check is blind to. This asserts the panel's
     * left edge against the PANE, which covers the whole ancestor chain in one number.
     * (parts-search, 2026-08-25, reasoning about what the new yardstick still could not see.) */
    /* PHRASE HEADROOM AS A ROW, not a console warning nobody reads: "does not truncate TODAY"
     * and "has room" are different claims.
     * MEASURE need AGAINST AN OFFSCREEN nowrap PROBE. Do NOT use clientWidth - scrollWidth:
     * for a block span with overflow:hidden, scrollWidth is max(clientWidth, content), so that
     * expression SATURATES AT 0 for anything that fits, whether it fits by 1px or by 180px. It
     * still goes negative correctly when text overflows, so it looks like a working metric.
     * Two apps independently reported "0px headroom, one character from truncating" off it;
     * remeasured with this probe, neither had less than 141px of slack. A metric that can only
     * return one value on success is not evidence of success. */
    var spans = [].slice.call(panel.querySelectorAll('.anp-phrase span'));
    if (spans.length) {
      var probe = document.createElement('span');
      probe.style.cssText = 'position:absolute;visibility:hidden;white-space:nowrap;font:' +
                            getComputedStyle(spans[0]).font;
      document.body.appendChild(probe);
      var worst = 0, worstTxt = '', tight = 0;
      spans.forEach(function (sp) {
        probe.textContent = sp.textContent;
        var need = Math.ceil(probe.getBoundingClientRect().width);
        var have = Math.round(sp.getBoundingClientRect().width);
        var slack = have - need;
        if (worstTxt === '' || slack < worst) { worst = slack; worstTxt = sp.textContent.trim().slice(0, 40); }
        if (slack < 8) tight++;
      });
      probe.remove();
      var headOk = worst >= 8;
      if (!headOk) ok = false;
      rows.push({ what: 'phrase headroom', want: 'at least 8px of slack on every phrase',
                  got: worst + 'px on ' + JSON.stringify(worstTxt) + (tight > 1 ? ' (' + tight + ' tight)' : ''),
                  pass: headOk });
    }
    var fam = getComputedStyle(panel.querySelector('.anp-phrase span') || panel).fontFamily;
    var famOk = /Satoshi/.test(fam);
    if (!famOk) ok = false;
    rows.push({ what: 'phrase typeface', want: 'Satoshi', got: fam.split(',')[0], pass: famOk });
    return { ok: ok, rows: rows };
  }

  /* checkSend(apiBase) - prove the send path EXISTS, without sending anything.
   * gate() fails OPEN on purpose, so a broken probe cannot block a user from sending. The
   * consequence, which kicad found in itself: A MISSING GATE READS AS AN ALLOWED GATE. Its
   * /updater/status route had been lost in a rebuild, the gate got HTML, caught, and returned
   * open, so the version gate had been silently no-opping. Nothing anywhere said so.
   * This makes that visible. It never posts a prompt: the run-prompt route is probed with
   * OPTIONS, so it can report "wired" without creating a thread in anyone's list. */
  function checkSend(base) {
    base = base == null ? '' : base;
    var rows = [], ok = true;
    function add(what, want, got, pass) { rows.push({what: what, want: want, got: got, pass: pass}); if (!pass) ok = false; }
    return fetch(base + '/updater/status', {cache: 'no-store'})
      .then(function (r) { return r.text().then(function (t) { return {s: r.status, t: t}; }); })
      .then(function (res) {
        var v = null, parsed = false;
        try { var j = JSON.parse(res.t); parsed = true; v = j && j.updater && j.updater.current_version; } catch (e) {}
        add('gate route wired', '200 with JSON', res.s + (parsed ? ' JSON' : ' NOT JSON'), res.s === 200 && parsed);
        add('gate reports a version', 'updater.current_version', String(v), !!v);
        if (v) add('version meets the minimum', MIN_API.join('.'), String(v), verGte(verNum(v), MIN_API));
      })
      .catch(function (e) { add('gate route wired', '200 with JSON', 'FETCH FAILED: ' + e.message, false); })
      .then(function () {
        /* PROBE A NONSENSE PATH TOO, AND REQUIRE THE TWO TO DIFFER.
         * "not 404" was too weak an assertion. kicad's do_OPTIONS returned 204 for EVERY path
         * unconditionally, so this row was green for any string at all, including routes that
         * exist in no method. An app could fix its GET catch-all, still have a blanket
         * preflight, and keep a green row that tests nothing. Comparing against a path that
         * cannot exist makes the row self-validating: if they answer identically, the server
         * is answering the SHAPE of the question rather than the question. */
        var nonsense = '/__anp_probe_' + String(Math.floor(1e9 * 0.6180339887)) + '__';
        return Promise.all([
          fetch(base + '/ai-threads/run-prompt', {method: 'OPTIONS'}).then(function (r) { return r.status; },
            function () { return 'ERR'; }),
          fetch(base + nonsense, {method: 'OPTIONS'}).then(function (r) { return r.status; },
            function () { return 'ERR'; })
        ]).then(function (both) {
          var real = both[0], fake = both[1];
          add('send route wired', 'answers, and differently from a path that cannot exist',
              'route ' + real + ', nonsense ' + fake,
              real !== 'ERR' && real !== 404 && real !== fake);
        });
      })
      .then(function () {
        /* THE STATUS ROUTE, added for Hydrogen 1.0.187+. It is a THIRD proxy route and no
         * dashboard had it before 2.22.0, so it is the row most likely to be red. A GET with
         * a job id that cannot exist must still be ANSWERED (any non-404), because a 404 here
         * means the route was never proxied and progress can never be reported. */
        return fetch(base + '/ai-threads/run-prompt/status?job=__anp_probe__')
          .then(function (r) { return r.status; }, function () { return 'ERR'; })
          .then(function (st) {
            add('progress route wired', 'answers (not 404)', String(st), st !== 'ERR' && st !== 404);
          });
      })
      .then(function () { return {ok: ok, rows: rows}; });
  }

  root.AdomNewbiePanel = { mount: mount, toast: toast, selfCheck: selfCheck, copyText: copyText,
                           checkSend: checkSend, version: '2.22.0',
                           TWO_COL_MIN: TWO_COL_MIN, PHRASE_BUDGET: PHRASE_BUDGET };
})(typeof window !== 'undefined' ? window : this);
